import { env } from "./env.js";

// Keep the application import dynamic: environment files must be loaded before
// Prisma's generated client evaluates its datasource configuration.
const { buildApp } = await import("./app.js");
const app = await buildApp();

try {
  await app.listen({ host: env.API_HOST, port: env.API_PORT });
} catch (error) {
  app.log.error(error);
  process.exit(1);
}
